import { ref } from 'vue';

export function useFigmaIframe() {
  const menus = ref([
    {
      title: '토트넘 홈페이지<br><span>(PC / Tablet / Mobile)</span>',
      url: 'https://embed.figma.com/design/0HBAn5oJwuR7rxsnZlkfGB/Mankyu_Tottenham_Hotspur_Figma?node-id=1-467&embed-host=share',
    },
    {
      title: '삼성 바이오 로직스<br><span>(PC / Tablet / Mobile)</span>',
      url: 'https://embed.figma.com/design/6XBRKYT47lFFTUyH2bkWud/Mankyu_Samsung_Biologics_Figma?node-id=1-221&embed-host=share',
    },
  ]);

  const selectedUrl = ref(menus.value[0].url);

  function selectMenu(url) {
    selectedUrl.value = url;
  }

  return {
    menus,
    selectedUrl,
    selectMenu,
  };
}